Translate("ruRU", "ashenvale", {
	title = "Ясеневый лес",
	sections = {
		{
			title = "Обзор",
			text = [=[Ясеневый лес — великий лес {link:night-elves}ночных эльфов{/link}, край исполинских деревьев, серебряных озер и белых руин на севере {link:kalimdor}Калимдора{/link}. Он тянется от серого моря у {link:the-zoram-strand}Зорам{/link}ского взморья на западе до реки, что отделяет его от {link:azshara}Азшары{/link}, на востоке. К северу лежат {link:darkshore}Темные берега{/link} и {link:felwood}Оскверненный лес{/link}, к югу — {link:stonetalon-mountains}Когтистые горы{/link} и {link:the-barrens}Степи{/link}. Десять тысяч лет ночные эльфы хранили его как священную чащу. Теперь он священен не только для них. В его восточных долинах звенят топоры {link:horde}Орды{/link}, и лес стал самым старым и самым горьким полем битвы между эльфами и {link:orcs}орк{/link}ами.]=],
		},
		{
			title = "Истоки",
			text = [=[Деревья Ясеневого леса старше любой летописи. До {link:great-sundering}Великого Раскола{/link} вдоль его западного берега стояли города эльфов, и город {link:the-zoram-strand}Зорам{/link} смотрел на море. Когда {link:well-of-eternity}Источник Вечности{/link} был уничтожен, море поднялось и поглотило Зорам, а руины старых храмов остались разбросаны по лесам: {link:the-ruins-of-ordil-aran}Ордил'Аран{/link}, {link:bathran-s-haunt}Убежище Батрана{/link}, {link:the-ruins-of-stardust}Руины Звездной Пыли{/link} и город {link:xavian}Ксавиан{/link} на востоке. После войны ночные эльфы поселились в тени {link:mount-hyjal}горы Хиджал{/link} и посвятили себя пути друидов и полубога {link:cenarius}Кенария{/link}. Пока друиды спали в {link:emerald-dream}Изумрудном Сне{/link}, {link:sentinels}Часовые{/link}, которых вела {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link}, стерегли лес на протяжении веков Долгого Бдения. Ни одна летопись не говорит, когда были основаны {link:astranaar}Астранаар{/link} и другие селения леса.]=],
		},
		{
			title = "Наши дни",
			text = [=[Ясеневый лес не знает покоя со времен {link:third-war}Третьей войны{/link}. {link:sentinels}Часовые{/link} удерживают {link:astranaar}Астранаар{/link}, Заставу Мейстры, {link:silverwind-refuge}Приют Серебряного Ветра{/link} и Лесную Песнь, но ряды их редки, а дороги длинны. {link:furbolgs}Фурболги{/link} племен Колючего Меха и Гиблой Чащи, некогда друзья эльфов, отравлены порчей, что ползет из Оскверненного леса, и нападают на каждого путника. {link:satyrs}Сатиры{/link} владеют Ночной поляной, {link:satyrnaar}Сатирнаар{/link}ом и {link:xavian}Ксавиан{/link}ом. {link:naga}Наги{/link} вернулись в затопленные руины города {link:the-zoram-strand}Зорам{/link}а, а культ {link:twilight-s-hammer}Сумеречного Молота{/link} собирается в залитых водой залах {link:blackfathom-deeps}Непроглядной Пучины{/link}. На востоке {link:orcs}орк{/link}и клана Песни Войны рубят лес для Орды под охраной Заставы Расщепленного Дерева. На западном берегу они возвели второй форпост — {link:zoram-gar-outpost}Зорам'гар{/link}. На каждое срубленное дерево эльфы отвечают стрелами, и с каждым годом война двух народов уходит всё глубже в чащу.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:night-elves}Ночные эльфы{/link}.{/b} {link:sentinels}Часовые{/link}, друиды и жрицы, которые удерживают селения леса и сражаются, чтобы сберечь его целым.
• {b}Дриады.{/b} Дочери полубога Кенария по-прежнему танцуют на {link:moonglade}поляна{/link}х Приюта в Ночных Лесах и Святилища Эссины.
• {b}{link:horde}Орда{/link}.{/b} {link:orcs}Орки{/link} клана Песни Войны, а с ними тролли, {link:tauren}таурен{/link}ы и гоблины, удерживают Заставу Расщепленного Дерева, лесозаготовки востока и {link:zoram-gar-outpost}Форт Зорам'гар{/link} на побережье.
• {b}{link:forsaken}Отрекшиеся{/link}.{/b} Аптекари {link:undercity}Подгорода{/link} прокрались в курганы и руины эльфов.
• {b}{link:furbolgs}Фурболги{/link}.{/b} Обезумевшие племена Колючего Меха на севере и Гиблой Чащи на юге, а также фурболги Кровавого Клыка, что идут за свирепым королем.
• {b}{link:satyrs}Сатиры{/link}.{/b} Сатиры Скверного Мускуса, Мрачного Сердца и сатиры {link:xavian}Ксавиан{/link}а поклоняются демонам в разрушенных храмах востока.
• {b}{link:naga}Наги{/link}.{/b} Наги Гневного Хвоста обитают на {link:the-zoram-strand}Зорам{/link}ском взморье и в водах Непроглядной Пучины.
• {b}Демоны.{/b} Стражи Скверны и инферналы всё еще бродят по каньону, где пал {link:mannoroth}Маннорот{/link}.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:the-drowned-city}Затонувший город{/link}.{/b} В дни {link:great-sundering}Раскол{/link}а море забрало {link:the-zoram-strand}Зорам{/link}. Его правители, его кольцо и его тайны ушли на дно вместе с ним.
• {b}Долгое Бдение.{/b} Десять тысяч лет {link:sentinels}Часовые{/link} охраняли Ясеневый лес, пока друиды спали, и лес стал глубоким и тихим.
• {b}Приход {link:orcs}орк{/link}ов.{/b} В Третью войну орки, которых вел {link:grom-hellscream}Гром Адский Крик{/link}, пришли в Ясеневый лес рубить деревья для своего нового дома. Часовые нанесли ответный удар, и сам {link:cenarius}Кенарий{/link} поднялся на защиту леса. Гром и его воины испили из источника, оскверненного кровью демона {link:mannoroth}Маннорот{/link}а, и в этой ярости убили полубога. Позже, в каньоне восточного леса, Гром сразил демона Маннорота и освободил свой народ от проклятия крови, но умер от ран.
• {b}Хиджал.{/b} В {link:battle-of-mount-hyjal}битве у горы Хиджал{/link} эльфы, орки и люди встали плечом к плечу против {link:archimonde}Архимонда{/link}, и Легион был сокрушен. Союз того дня не пережил победы.
• {b}Наши дни.{/b} {link:horde}Орда{/link} по-прежнему рубит деревья Ясеневого леса. {link:night-elves}Ночные эльфы{/link} так и не смирились с этим.]=],
		},
		{
			title = "Предания леса",
			text = [=[• Говорят, что Фолиант {link:the-howling-vale}Мел'Тандрис{/link}, который хранится в разрушенном святилище у границы Оскверненного леса, сам записывает на своих листах важные события. Никто не понимает, как это происходит.
• Фурболг {link:krolg}Кролг{/link} живет один у Озера Мистраль. Он говорит только с сородичами и винит эльфов в гибели своего народа.
• Охотники Заставы Расщепленного Дерева рассказывают о трех великих зверях леса: это медведь {link:ursangous}Урсангус{/link}, ночной саблезуб {link:shadumbra}Шадумбра{/link} и гипп{link:ogres}огр{/link}иф {link:sharptalon}Острокоготь{/link}. {link:odo-the-blindwatcher}Одо{/link}леть всех троих — испытание, которое покажет, чего стоит любой охотник.
• {link:satyrs}Сатиры{/link} похитили у дриад Ветвь Кенария, и дриады этого не простили.]=],
		},
	},
})

Translate("ruRU", "astranaar", {
	title = "Астранаар",
	sections = {
		{
			title = "Обзор",
			text = [=[Астранаар — главное поселение ночных эльфов в Ясеневом лесу. Он стоит на острове посреди озера в самом сердце леса, и с берегом его соединяют мосты из белого камня. Здесь командует Часовыми этого края охотница {link:raene-wolfrunner}Раэна Волчья Бегунья{/link}, и отсюда разведчицы уезжают во все концы леса. В поселении есть таверна, гнездовье гипп{link:ogres}огр{/link}ифов и небольшой рынок эльфийских мастеров. Но оно стало и домом тревог. Его часовые доносят, что {link:furbolgs}фурболг{/link}ов на севере становится всё больше, в одном из домов лежит больной ребенок, а война с Ордой с каждым годом подступает всё ближе к мостам.]=],
		},
	},
})

Translate("ruRU", "maestra-s-post", {
	title = "Застава Мейстры",
	aliases = { "Мейстра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Застава Мейстры — небольшой эльфийский форпост на северо-западе Ясеневого леса, на дороге, что спускается с {link:darkshore}Темных берегов{/link}. Это первый приют, который путник из {link:auberdine}Аубердин{/link}а находит в лесу. {link:morgan-s-vigil}Дозор{/link} здесь несут {link:sentinels}Часовые{/link}, и здесь же друид {link:orendil-broadleaf}Орендил Широкий Лист{/link} готовит свои снадобья. Паладин-человек {link:delgren-the-purifier}Делгрен Очиститель{/link} сделал заставу своей опорой в войне против культа Темной Пряди, и его гонцы возят припасы на север, в Аубердин. Друидов, которые только что пробудились от Изумрудного Сна, отправляют сюда, где их встречают.]=],
		},
	},
})

Translate("ruRU", "bathran-s-haunt", {
	title = "Убежище Батрана",
	sections = {
		{
			title = "Обзор",
			text = [=[Убежище Батрана — эльфийские руины в северных холмах Ясеневого леса, чуть южнее границы Темных берегов. Когда-то среди его камней росло растение, которое называют «Волосы Батрана», и друиды ценили его как лекарство от недугов духа. Руины больше не пусты. Среди стен разбили лагерь {link:forsaken}Отрекшиеся{/link}, и их травники собирают то, что там растет, ради собственных целей. Друидов Заставы Мейстры их присутствие очень тревожит.]=],
		},
	},
})

Translate("ruRU", "the-ruins-of-ordil-aran", {
	title = "Руины Ордил'Арана",
	aliases = { "Ордил'Аран" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ордил'Аран — разрушенный город древних эльфов на севере Ясеневого леса, к северо-востоку от Заставы Мейстры. Его имя напоминает о городах-близнецах {link:ameth-aran}Амет'Аран{/link} и {link:bashal-aran}Башал'Аран{/link} на {link:darkshore}Темных берегах{/link}, которые были построены для высокорожденных в дни {link:queen-azshara}королевы Азшары{/link}. Теперь среди его камней ведут раскопки чернокнижники культа Темной Пряди. Один из них носил при себе самоцвет душ, в котором была заключена тайна силы культа, пока паладин {link:delgren-the-purifier}Делгрен Очиститель{/link} не послал воителя отнять его.]=],
		},
	},
})

Translate("ruRU", "the-zoram-strand", {
	title = "Зорамское взморье",
	aliases = { "Зорам" },
	sections = {
		{
			title = "Обзор",
			text = [=[Зорамское взморье — западное побережье Ясеневого леса, берег серого песка и разбитых колонн. Под волнами лежит Зорам, город эльфов, который море поглотило в дни Великого {link:great-sundering}Раскол{/link}а. Долгие века он был почти забыт. Теперь в него вернулись {link:naga}наги{/link}, и никто не знает, чего они ищут. Наги Гневного Хвоста вместе с гидрами удерживают берег и его острова. На северном краю взморья {link:ogres}огр{/link}омный храм, наполовину ушедший в море, ведет в глубины {link:blackfathom-deeps}Непроглядной Пучины{/link}.]=],
		},
	},
})

Translate("ruRU", "zoram-gar-outpost", {
	title = "Форт Зорам'гар",
	aliases = { "Зорам'гар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Зорам'гар — форпост Орды на {link:the-zoram-strand}Зорам{/link}ском взморье, лагерь {link:orcs}орк{/link}ов и троллей на косе у самого моря. Его построили, чтобы закрепить за Ордой западное побережье Ясеневого леса и следить за {link:naga}нага{/link}ми и руинами Непроглядной Пучины. Командует им орк {link:karang-amakkar}Каранг Амаккар{/link}. Тролль {link:je-neu-sancrea}Дже'неу Санкри{/link} из {link:earthen-ring}Служителей Земли{/link} изучает море с его берега. Лагерю приходится тяжело. На него нападают наги, не раз его атаковала {link:ogres}огр{/link}омная гидра, а между ним и Заставой Расщепленного Дерева стоят {link:furbolgs}фурболг{/link}и Колючего Меха.]=],
		},
	},
})

Translate("ruRU", "lake-falathim", {
	title = "Озеро Фалатим",
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Фалатим лежит у подножия гор на западе Ясеневого леса. На его острове стояло святилище, где эльфы некогда хранили сияющий самоцвет, пока святилище не было захвачено. Теперь берегом владеют {link:murlocs}мурлоки{/link} племени Соленой Слюны. Именно сюда пришел в поисках самоцвета эльф {link:teronis}Теронис{/link}, и здесь друзья нашли его тело: растерзанное когтями мурлоков, оно лежало на острове нетронутым.]=],
		},
	},
})

Translate("ruRU", "the-shrine-of-aessina", {
	title = "Святилище Эссины",
	aliases = { "Эссина" },
	sections = {
		{
			title = "Обзор",
			text = [=[Святилище Эссины — потаенная {link:moonglade}поляна{/link} в горах на западе Ясеневого леса; ее окружают утесы, и ведут к ней немногие тропы. На ней стоит святилище великой и тонкой силы, где собирается магия леса. Там живут дриады, среди них {link:therysil}Терисил{/link} и {link:illiyana}Иллияна{/link}, а поляну стережет часовая {link:sentinel-melyria-frostshadow}Мелирия Ледяная Тень{/link}. Те, кто хочет обновить чары, приходят сюда, кладут свою работу в чашу святилища и ждут сияния.]=],
		},
	},
})

Translate("ruRU", "fire-scar-shrine", {
	title = "Святилище Огненной Расщелины",
	aliases = { "Огненная Расщелина" },
	sections = {
		{
			title = "Обзор",
			text = [=[Святилище Огненной Расщелины — место великого зла на юго-западе Ясеневого леса. Земля здесь выжжена, а деревья мертвы. Здесь устроил логово {link:orcs}орк{/link}-чернокнижник {link:ilkrud-magthrull}Илкруд Магтрулл{/link}, и на его зов являются демоны. Среди пепла бродит демон Аккрилус. Когда-то эльфы считали, что Илкруд — всего лишь досадная помеха. Всё изменилось, когда паладин {link:delgren-the-purifier}Делгрен Очиститель{/link} узнал, что чернокнижник хранит записи о замыслах культа Темной Пряди.]=],
		},
	},
})

Translate("ruRU", "thistlefur-village", {
	title = "Деревня Колючего Меха",
	aliases = { "Логово Колючего Меха", "Колючий Мех" },
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Колючего Меха — дом {link:furbolgs}фурболгов{/link} племени Колючего Меха к северу от {link:astranaar}Астранаар{/link}а. Их хижины рассыпаны по лесу, а в конце деревни в глубь холма уходит пещера, которую называют Логовом Колючего Меха. Фурболги Колючего Меха не всегда были врагами, но теперь они осквернены, и за последние месяцы их стало намного больше. {link:sentinels}Часовые{/link} опасаются, что племя осмелеет настолько, что нападет на сам Астранаар. Боится их и {link:horde}Орда{/link}, ведь деревня перекрывает дорогу между {link:zoram-gar-outpost}Зорам'гар{/link}ом и Заставой Расщепленного Дерева.]=],
		},
	},
})

Translate("ruRU", "iris-lake", {
	title = "Озеро Ирис",
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Ирис лежит к востоку от {link:astranaar}Астранаар{/link}а — тихая вода с маленьким островком посередине. На этом островке покоится камень, который зовут Слезой Элуны, и больше его нет нигде в мире. Друиды говорят, что он способен смыть порчу. Когда дочь эльфа {link:pelturas-whitemoon}Пелтурас{/link}а Белой Луны лежала больная и ее мучили кошмары, облегчила их именно Слеза с Озера Ирис.]=],
		},
	},
})

Translate("ruRU", "the-ruins-of-stardust", {
	title = "Руины Звездной Пыли",
	sections = {
		{
			title = "Обзор",
			text = [=[Руины Звездной Пыли лежат к югу от {link:astranaar}Астранаар{/link}а, среди деревьев южного леса. Там почти ничего не осталось, кроме битого камня. Но среди руин собирается морозная пыль, и друиды знают, что она способна унять жар. Имя этого места старше любых записей, и эльфы говорят лишь, что его назвали в честь этой пыли.]=],
		},
	},
})

Translate("ruRU", "mystral-lake", {
	title = "Озеро Мистраль",
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Мистраль — широкая вода на юге Ясеневого леса, недалеко от входа в {link:the-talondeep-path}Туннель Когтя{/link}, что ведет в {link:stonetalon-mountains}Когтистые горы{/link}. Его воды ожили. Из них поднимаются оскверненные элементали и нападают на всё, что приблизится, и дорога между лесом и Когтистыми горами почти закрыта. Беседка на озере смотрит на эльфийский приют на его берегу, и как Часовым, так и Орде стало важно, кто наблюдает из нее. На южном берегу живет {link:krolg}Кролг{/link} — {link:furbolgs}фурболг{/link}, который избежал порчи, поразившей его сородичей.]=],
		},
	},
})

Translate("ruRU", "silverwind-refuge", {
	title = "Приют Серебряного Ветра",
	aliases = { "Серебряный Ветер" },
	sections = {
		{
			title = "Обзор",
			text = [=[Приют Серебряного Ветра — селение ночных эльфов на южном берегу Озера Мистраль. В нем есть свои торговцы, наставники и алхимики, а также гнездовье гипп{link:ogres}огр{/link}ифов. Его стражей командует часовая {link:sentinel-velene-starstrike}Велена Звездный Удар{/link}. В последнее время приют не знает отдыха, ведь озеро рядом с ним наполняется нечистыми элементалями. Велена узнала, кто их создает, и поклялась, что он за это заплатит.]=],
		},
	},
})

Translate("ruRU", "fallen-sky-lake", {
	title = "Зеркало Небес",
	sections = {
		{
			title = "Обзор",
			text = [=[Зеркало Небес лежит на юго-востоке Ясеневого леса. Когда-то эльфы собирали на его берегу лунные камни — камни, что упали с неба и несут в себе силу луны. Потом пришли древни Тенистой Чащи. Это искаженные древни, и их оракул собрал все упавшие лунные камни в собственный клад. Эльфы больше не ходят к озеру.]=],
		},
	},
})

Translate("ruRU", "raynewood-retreat", {
	title = "Приют в Ночных Лесах",
	aliases = { "Ночные Леса" },
	sections = {
		{
			title = "Обзор",
			text = [=[Приют в Ночных Лесах — высокая роща в сердце Ясеневого леса, которую венчает великое древо Ночных Лесов, и роща носит его имя. На ее {link:moonglade}поляна{/link}х играют дриады, которых зовут Смеющимися сестрами, а тропы стерегут воины {link:krueg-skullsplitter}Круг{/link}а Кенария. На вершине древа живет хранитель {link:keeper-ordanus}Орданус{/link}, сын полубога Кенария; его тайно перенесли сюда с вершин Когтистых гор, когда чернокнижница из {link:shadow-council}Совет{/link}а Теней стала искать его смерти. По склонам внизу бродят олени и {link:ogres}огр{/link}омные медведи, и среди них охотится ночной саблезуб {link:shadumbra}Шадумбра{/link}.]=],
		},
	},
})

Translate("ruRU", "the-howling-vale", {
	title = "Воющая долина",
	aliases = { "Мел'Тандрис" },
	sections = {
		{
			title = "Обзор",
			text = [=[Воющая долина лежит на севере Ясеневого леса, у границы {link:felwood}Оскверненного леса{/link}. Ее сердце — разрушенное святилище Мел'Тандрис, где хранится странная книга. Ее страницы благословила сама Мел'Тандрис, и силой, которую никто не может объяснить, они записывают великие события этого края. Недавно святилище захватили люди-волки. Их леденящий вой и дал долине имя. Книга показала Часовым, что эти твари связаны с пропавшей жрицей и с реликвией, которую называют {red:scythe-of-elune}Косой Элуны{/red}.]=],
		},
	},
})

Translate("ruRU", "night-run", {
	title = "Ночная поляна",
	sections = {
		{
			title = "Обзор",
			text = [=[Ночная поляна — долина на северо-востоке Ясеневого леса, которой владеют {link:satyrs}сатир{/link}ы. Ее храмы пропитаны кровью, и даже бывалым воинам там не по себе. Здесь высокорожденный лорд {link:athrikus-narassin}Атрикус Нарассин{/link} спрятал один из своих последних самоцветов душ, и плененная душа высокорожденного ждала внутри него, пока ее не освободили. Сатиры Ночной поляны держат у себя и масло, украденное у клана Песни Войны: они жгут его в своих ритуалах.]=],
		},
	},
})

Translate("ruRU", "satyrnaar", {
	title = "Сатирнаар",
	sections = {
		{
			title = "Обзор",
			text = [=[Сатирнаар — твердыня {link:satyrs}сатир{/link}ов Скверного Мускуса на востоке Ясеневого леса, руины, окутанные тенью Скверны. Это одно из мест, где лорд {link:athrikus-narassin}Атрикус Нарассин{/link} хранил самоцвет душ и где томилась в заточении душа высокорожденного. Как {link:night-run}Ночная поляна{/link} и {link:xavian}Ксавиан{/link}, когда-то это был храм. Паладин {link:delgren-the-purifier}Делгрен Очиститель{/link} слышал, будто история сатиров связана с историей ночных эльфов, но те, у кого он гостит, не желают об этом говорить.]=],
		},
	},
})

Translate("ruRU", "xavian", {
	title = "Ксавиан",
	sections = {
		{
			title = "Обзор",
			text = [=[Ксавиан — легендарный город древних эльфов, укрытый в холмах на востоке Ясеневого леса. Ученые рассказывают о его утраченных знаниях, и говорят, что воды его самого высокого водопада таят великую магию. Теперь его руинами правят {link:satyrs}сатир{/link}ы Ксавиана, и среди них есть разбойники, присягнувшие Скверне и призыватели адского пламени. Их хозяин, сатир {link:geltharis}Гелтарис{/link}, похитил у дриад Ветвь Кенария. Три сестры-дриады отправились в Ксавиан, чтобы вернуть ее. Живой оттуда вышла только одна, и ненадолго.]=],
		},
	},
})

Translate("ruRU", "forest-song", {
	title = "Лесная Песнь",
	aliases = { "Леса Ночной Песни" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лесная Песнь — святилище ночных эльфов в Лесах Ночной Песни на востоке Ясеневого леса, у границы {link:azshara}Азшары{/link}. Его хранит друид {link:kayneth-stillwind}Кайнет Тихий Ветер{/link}. Отсюда он читает донесения Часовых и ищет в них признаки зла, которое, как он опасается, движется по лесу. Святилище стоит рядом с лесозаготовками Орды и с руинами {link:xavian}Ксавиан{/link}а, где засели {link:satyrs}сатир{/link}ы, и его друидам редко спится спокойно.]=],
		},
	},
})

Translate("ruRU", "bough-shadow", {
	title = "Тенистая Крона",
	sections = {
		{
			title = "Обзор",
			text = [=[Тенистая Крона — великое древо в дальнем северо-восточном углу Ясеневого леса, за Лесной Песнью. Это одно из четырех деревьев, которые, по словам друидов, служат вратами в {link:emerald-dream}Изумрудный Сон{/link}. Под ним несут стражу зеленые драконороды, а над его кроной кружат {link:ogres}огр{/link}омные зеленые дракончики. Они никого не подпускают близко, и эльфы Лесной Песни оставляют их в покое.]=],
		},
	},
})

Translate("ruRU", "splintertree-post", {
	title = "Застава Расщепленного Дерева",
	aliases = { "Расщепленное Дерево" },
	sections = {
		{
			title = "Обзор",
			text = [=[Застава Расщепленного Дерева — твердыня Орды на востоке Ясеневого леса, обнесенный стеной лагерь из орочьих хижин на холме над дорогой в {link:burning-steppes}Степи{/link}. Она охраняет лесозаготовки клана Песни Войны и дороги, по которым их лес везут на юг. Ее воины, охотники и торговцы происходят из всех народов Орды. У ворот ворчит {link:orcs}орк{/link} {link:mastok-wrilehiss}Масток Врайлхисс{/link}, охотница {link:senani-thunderheart}Сенани Громовое Сердце{/link} назначает испытания молодым охотникам, а орк {link:ertog-ragetusk}Эртог Яростный Клык{/link} готовит набеги на эльфов. Редкая ночь проходит там без тревоги.]=],
		},
	},
})

Translate("ruRU", "warsong-lumber-camp", {
	title = "Лесозаготовки Песни Войны",
	aliases = { "Рабочий лагерь Песни Войны" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лесозаготовки Песни Войны лежат на дальнем востоке Ясеневого леса, у реки, что отделяет лес от {link:azshara}Азшары{/link}. Здесь батраки клана Песни Войны валят великие деревья эльфов и отправляют лес на юг, чтобы строить Орду и питать ее огонь. Среди пней ревут гоблинские крошшеры, а рубаки охраняют работников от стрел Часовых. Именно этот труд привел в {link:ashenvale}Ясеневый лес{/link} вождя Грома Адского Крика в Третью войну, и он не прекращался ни на день. Лагерь живет припасами: это пилы из {link:ratchet}Кабестан{/link}а, топоры из Пиратской бухты, масло и веревки, которые то и дело крадут {link:satyrs}сатир{/link}ы и {link:furbolgs}фурболг{/link}и.]=],
		},
	},
})

Translate("ruRU", "demon-fall-canyon", {
	title = "Каньон Гибели Демона",
	aliases = { "Гряда Гибели Демона", "Гибель Демона", "Холм Демонического Огня" },
	sections = {
		{
			title = "Обзор",
			text = [=[Каньон Гибели Демона — глубокое ущелье на юго-востоке Ясеневого леса, и его имя хранит память о самом славном деянии Третьей войны. В одном из каньонов этого леса {link:grom-hellscream}Гром Адский Крик{/link} вонзил свой топор во властителя преисподней {link:mannoroth}Маннорота{/link} и освободил {link:orcs}орк{/link}ов от крови демона, и там же он умер. Каньон так и не очищен. В нем несут стражу стражи Скверны, среди его скал тлеют инферналы, а на гряде над ним охотятся гончие Легиона. На Холме Демонического Огня к югу ими командует повелитель ужаса Диатор Искатель.]=],
		},
	},
})

Translate("ruRU", "the-dor-danil-barrow-den", {
	title = "Обитель Дор'Данил",
	aliases = { "Дор'Данил" },
	sections = {
		{
			title = "Обзор",
			text = [=[Обитель Дор'Данил лежит на юго-востоке Ясеневого леса, к востоку от дороги в {link:burning-steppes}Степи{/link}. Когда-то здесь спали ее друиды, и на их попечении находилась часть старого жезла. Потом пришли {link:forsaken}Отрекшиеся{/link}. Они разбили лагерь у курганов, сварили свои болезни и отравили друидов во сне. Духи друидов Дор'Данил восстали, отсеченные от тел и доведенные до безумия, и теперь бродят по курганам вместе с нежитью, которая их убила.]=],
		},
	},
})

Translate("ruRU", "silverwing-outpost", {
	title = "Аванпост Среброкрылых",
	aliases = { "Роща Среброкрылых" },
	sections = {
		{
			title = "Обзор",
			text = [=[Аванпост Среброкрылых — лагерь Часовых на юге Ясеневого леса, среди деревьев к западу от дорог, по которым {link:horde}Орда{/link} возит лес. Его скороходы пробираются через чащу, чтобы шпионить за {link:orcs}орк{/link}ами, а его воины готовы ударить по Заставе Расщепленного Дерева. Возглавляет его {link:duriel-moonfire}Дуриэль Лунный Огонь{/link}. Орда считает его кинжалом у своего бока, и ее налетчики поклялись его взять.]=],
		},
	},
})

Translate("ruRU", "bloodtooth-camp", {
	title = "Лагерь Кровавого Клыка",
	aliases = { "Кровавый Клык" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Кровавого Клыка — логово {link:furbolgs}фурболг{/link}а Рана Кровавого Клыка и его стражей на юге Ясеневого леса, у края Степей. Ран — самый свирепый из оскверненных фурболгов, король среди своего племени, и порча лишь сделала его сильнее. Даже другие фурболги боятся того, что выходит из этого лагеря.]=],
		},
	},
})

Translate("ruRU", "greenpaw-village", {
	title = "Деревня Зеленой Лапы",
	aliases = { "Тотемный курган Гиблой Чащи" },
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Зеленой Лапы — дом {link:furbolgs}фурболг{/link}ов Гиблой Чащи; она лежит к югу от дороги, восточнее {link:astranaar}Астранаар{/link}а и западнее Реки Фалфаррен. В ее сердце стоит тотемный курган племени. Племя Гиблой Чащи малочисленнее, чем {link:thistlefur-village}Колючий Мех{/link}, но свирепее, и его фурболги нападают на путников на дороге. По ним наносили удары и {link:sentinels}Часовые{/link}, и {link:horde}Орда{/link}. Когда на их кургане подняли знамя Орды, их вождь вышел защитить честь своего племени и пал.]=],
		},
	},
})

Translate("ruRU", "raene-wolfrunner", {
	title = "Раэна Волчья Бегунья",
	subtitle = "Командир Часовых Астранаара",
	found = "Астранаар, рядом с двумя ее зверями",
	hint = [=[Поговорите с охотницей, которая командует Часовыми Астранаара.]=],
	allegiance = "Часовые · Дарнасс",
	aliases = { "Раэна" },
	sections = {
		{
			title = "Обзор",
			text = [=[Раэна Волчья Бегунья возглавляет {link:sentinels}Часовых{/link} {link:astranaar}Астранаар{/link}а. Она охотница, рядом с ней всегда волк и большая кошка, и каждое донесение из леса проходит через ее руки. Она шлет просьбы о помощи до самых Темных берегов, и те, кто откликается, находят ее спокойной, серьезной и очень стесненной в воинах.]=],
		},
		{
			title = "Значение",
			text = [=[Раэна удерживает сердце Ясеневого леса для ночных эльфов в ту пору, когда враги теснят их со всех сторон. Ее война идет сразу на два фронта: против Орды и против порчи, которая превратила {link:furbolgs}фурболг{/link}ов леса в зверей.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она посылает разведчиков и добровольцев против племен Колючего Меха и Гиблой Чащи.
• Она продолжила дело своего друга, эльфа {link:teronis}Теронис{/link}а, после его смерти.
• Она хранит череп короля {link:furbolgs}фурболг{/link}ов и старый жезл на почетном месте в {link:astranaar}Астранаар{/link}е.]=],
		},
	},
	chapters = {
		{
			title = "Смерть эльфа Терониса",
			hint = [=[Ищите вести о пропавшем друге охотницы Раэны на острове к западу.]=],
			text = [=[{link:teronis}Теронис{/link}, друг охотницы Раэны, ушел на запад, к Озеру Фалатим, в поисках самоцвета и не вернулся. Он разыскивал части жезла, который создал покойный колдун {link:dar}Дар{/link}тол: Теронис верил, что жезл поможет сдержать нападения {link:furbolgs}фурболг{/link}ов. Его тело нашли на острове, иссеченное когтями {link:murlocs}мурлок{/link}ов. Раэна отложила свое горе. Время скорби придет позже. Теперь важно было одно: чтобы его труд не пропал даром.]=],
		},
		{
			title = "Жезл колдуна Дартола",
			hint = "Соберите части жезла и найдите дриаду у лунного колодца.",
			text = [=[По записям в дневнике, который вел {link:teronis}Теронис{/link}, части жезла удалось проследить по всему лесу: одну стерегли оскверненные древни у Оскверненного леса, другая была спрятана у обреченных друидов {link:the-dor-danil-barrow-den}Дор'Данил{/link}. Дриада {link:shael-dryn}Шаэл'дрин{/link} соединила их, а потаенное святилище вернуло жезлу силу. Он мог придать своему владельцу облик {link:furbolgs}фурболг{/link}а. Раэна не знала, что Теронис собирался с ним делать. Она догадывалась: он надеялся поговорить с фурболгом, которого еще не коснулся мох Скверны.]=],
		},
		{
			title = "Череп фурболга Рана Кровавого Клыка",
			hint = [=[Узнайте, чего неоскверненный фурболг требует от своих сородичей.]=],
			text = [=[Жезл привел к {link:furbolgs}фурболг{/link}у {link:krolg}Кролг{/link}у: он избежал порчи и винил эльфов во всем, что постигло его народ. И все же Кролг не желал, чтобы за это страдали эльфийские дети. Он попросил, чтобы его племя само навело у себя порядок, и так был убит {link:ran-bloodtooth}Ран Кровавый Клык{/link}, самый свирепый из оскверненных фурболгов. Раэна выставила его череп и жезл колдуна {link:dar}Дар{/link}тола там, где их мог видеть весь {link:astranaar}Астранаар{/link}, и сказала, что {link:teronis}Теронис{/link} был бы горд.]=],
		},
	},
	mentions = {
		{ text = "Поход в {link:ashenvale}Ясеневый лес{/link}" },
		{ text = "Упреждающая оборона" },
		{ text = "Устранение угрозы" },
		{ text = "Очищение охотницы Раэны" },
	},
	bonds = {
		{ id = "teronis", name = "Теронис", note = "ее друг, чье дело она завершила" },
		{ id = "shael-dryn", name = "Шаэл'дрин", note = "помогла воссоздать жезл колдуна Дартола" },
